def reassign_fb_bots_and_fix_female_avatars(apps, schema_editor):
    UserProfile = apps.get_model('authentication', 'UserProfile')
    OfficeSeat = apps.get_model('office', 'OfficeSeat')
    OfficePresence = apps.get_model('office', 'OfficePresence')

    all_users = list(UserProfile.objects.all())

    # 1. Chuyển 5 FB bots sang phòng Khảo thí (room='exam') với seat_index 3..7
    for u in all_users:
        email = (u.email or '').strip().lower()
        if email.startswith('bot.fb.') or 'bot.fb.' in email:
            seat_idx = BOT_ORDER.get(email, 3)
            OfficeSeat.objects.update_or_create(
                user=u,
                defaults={
                    'room': 'exam',
                    'seat_index': seat_idx,
                    'is_head': False,
                },
            )
        elif 'assistant' in email or (u.role or '').upper() == 'BOT' and 'trợ lý' in (u.name or '').lower():
            OfficeSeat.objects.update_or_create(
                user=u,
                defaults={
                    'room': 'common',
                    'seat_index': 0,
                    'is_head': True,
                },
            )

    # 2. Cập nhật giới tính và tóc cho nhân sự nữ
    for u in all_users:
        name = (u.name or '').lower().strip()
        email = (u.email or '').lower().strip()
        is_female = any(f in name for f in FEMALE_NAMES) or any(f in email.split('@')[0] for f in ['ha', 'lien', 'phuong', 'linh', 'trang', 'thao'])
        if is_female:
            presence, _ = OfficePresence.objects.get_or_create(user=u)
            cfg = dict(presence.avatar_config) if isinstance(presence.avatar_config, dict) else {}
            cfg['gender'] = 'female'
            if not cfg.get('hairStyle'):
                cfg['hairStyle'] = 'bob' if 'khánh hà' in name or 'khanh ha' in name else 'ponytail'
            if not cfg.get('shirt'):
                cfg['shirt'] = '#F2B8B5' if 'hà' in name or 'ha' in name else '#E7C6D3'
            presence.avatar_config = cfg
            presence.save(update_fields=['avatar_config'])


